    /**
     * Method to retrieve the Observation via ObservationFetchOneSummary
     * @param 	summary ObservationFetchOneSummary 
     * @return 	ObservationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Observation getObservation( ObservationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ObservationFetchOneSummary arg cannot be null" );
    	
    	Observation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Observation
        	// --------------------------------------
        	CompletableFuture<Observation> futureEntity = queryGateway.query(new FindObservationQuery( new LoadObservationFilter( summary.getObservationId() ) ), ResponseTypes.instanceOf(Observation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Observation with id " + summary.getObservationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


